 "data": [
  {
   "name": "inc",
   "url": {
    "%type%": "esql",
    "query": "FROM servicenow-incidents-*\n| WHERE TO_STRING(number) LIKE \"INC*\" AND opened_at >= NOW() - 30 days\n| INLINE STATS last_seen = MAX(@timestamp) BY number\n| WHERE @timestamp == last_seen AND TO_INTEGER(priority) IN (1, 2) AND TO_STRING(state_name) NOT IN (\"On Hold\", \"Resolved\", \"Closed\", \"Canceled\", \"Cancelled\")\n| EVAL domain = CASE(TO_LOWER(COALESCE(TO_STRING(ci.class_name), \"\")) == \"\" OR TO_LOWER(COALESCE(TO_STRING(ci.class_name), \"\")) == \"null\", \"Unknown\", TO_LOWER(COALESCE(TO_STRING(ci.class_name), \"\")) LIKE \"*infrastructure service*\", \"Other\", TO_LOWER(COALESCE(TO_STRING(ci.class_name), \"\")) LIKE \"*esx*\" OR TO_LOWER(COALESCE(TO_STRING(ci.class_name), \"\")) LIKE \"*vmware*\" OR TO_LOWER(COALESCE(TO_STRING(ci.class_name), \"\")) LIKE \"*vcenter*\" OR TO_LOWER(COALESCE(TO_STRING(ci.class_name), \"\")) LIKE \"*vsphere*\" OR TO_LOWER(COALESCE(TO_STRING(ci.class_name), \"\")) LIKE \"*hyper_v*\" OR TO_LOWER(COALESCE(TO_STRING(ci.class_name), \"\")) LIKE \"*hyper-v*\", \"VMware\", TO_LOWER(COALESCE(TO_STRING(ci.class_name), \"\")) LIKE \"*sql*\" OR TO_LOWER(COALESCE(TO_STRING(ci.class_name), \"\")) LIKE \"*oracle*\" OR TO_LOWER(COALESCE(TO_STRING(ci.class_name), \"\")) LIKE \"*db2*\" OR TO_LOWER(COALESCE(TO_STRING(ci.class_name), \"\")) LIKE \"*database*\" OR TO_LOWER(COALESCE(TO_STRING(ci.class_name), \"\")) LIKE \"*postgres*\" OR TO_LOWER(COALESCE(TO_STRING(ci.class_name), \"\")) LIKE \"*mongo*\" OR TO_LOWER(COALESCE(TO_STRING(ci.class_name), \"\")) LIKE \"*sybase*\" OR TO_LOWER(COALESCE(TO_STRING(ci.class_name), \"\")) LIKE \"*_db*\" OR TO_LOWER(COALESCE(TO_STRING(ci.class_name), \"\")) LIKE \"*db_*\", \"Database\", TO_LOWER(COALESCE(TO_STRING(ci.class_name), \"\")) LIKE \"*mq*\" OR TO_LOWER(COALESCE(TO_STRING(ci.class_name), \"\")) LIKE \"*websphere*\" OR TO_LOWER(COALESCE(TO_STRING(ci.class_name), \"\")) LIKE \"*jboss*\" OR TO_LOWER(COALESCE(TO_STRING(ci.class_name), \"\")) LIKE \"*tomcat*\" OR TO_LOWER(COALESCE(TO_STRING(ci.class_name), \"\")) LIKE \"*weblogic*\" OR TO_LOWER(COALESCE(TO_STRING(ci.class_name), \"\")) LIKE \"*iis*\" OR TO_LOWER(COALESCE(TO_STRING(ci.class_name), \"\")) LIKE \"*app_server*\" OR TO_LOWER(COALESCE(TO_STRING(ci.class_name), \"\")) LIKE \"*application server*\" OR TO_LOWER(COALESCE(TO_STRING(ci.class_name), \"\")) LIKE \"*web server*\" OR TO_LOWER(COALESCE(TO_STRING(ci.class_name), \"\")) LIKE \"*web_server*\" OR TO_LOWER(COALESCE(TO_STRING(ci.class_name), \"\")) LIKE \"*middleware*\", \"Middleware\", TO_LOWER(COALESCE(TO_STRING(ci.class_name), \"\")) LIKE \"*kubernetes*\" OR TO_LOWER(COALESCE(TO_STRING(ci.class_name), \"\")) LIKE \"*gke*\" OR TO_LOWER(COALESCE(TO_STRING(ci.class_name), \"\")) LIKE \"*cloud*\" OR TO_LOWER(COALESCE(TO_STRING(ci.class_name), \"\")) LIKE \"*gcp*\" OR TO_LOWER(COALESCE(TO_STRING(ci.class_name), \"\")) LIKE \"*container*\", \"Cloud\", TO_LOWER(COALESCE(TO_STRING(ci.class_name), \"\")) LIKE \"*switch*\" OR TO_LOWER(COALESCE(TO_STRING(ci.class_name), \"\")) LIKE \"*router*\" OR TO_LOWER(COALESCE(TO_STRING(ci.class_name), \"\")) LIKE \"*ups*\" OR TO_LOWER(COALESCE(TO_STRING(ci.class_name), \"\")) LIKE \"*firewall*\" OR TO_LOWER(COALESCE(TO_STRING(ci.class_name), \"\")) LIKE \"*load bal*\" OR TO_LOWER(COALESCE(TO_STRING(ci.class_name), \"\")) LIKE \"*lb_*\" OR TO_LOWER(COALESCE(TO_STRING(ci.class_name), \"\")) LIKE \"*network*\" OR TO_LOWER(COALESCE(TO_STRING(ci.class_name), \"\")) LIKE \"*wireless*\" OR TO_LOWER(COALESCE(TO_STRING(ci.class_name), \"\")) LIKE \"*access point*\" OR TO_LOWER(COALESCE(TO_STRING(ci.class_name), \"\")) LIKE \"*ip_*\" OR TO_LOWER(COALESCE(TO_STRING(ci.class_name), \"\")) LIKE \"*ip *\" OR TO_LOWER(COALESCE(TO_STRING(ci.class_name), \"\")) LIKE \"*netgear*\" OR TO_LOWER(COALESCE(TO_STRING(ci.class_name), \"\")) LIKE \"*pdu*\" OR TO_LOWER(COALESCE(TO_STRING(ci.class_name), \"\")) LIKE \"*big-ip*\" OR TO_LOWER(COALESCE(TO_STRING(ci.class_name), \"\")) LIKE \"*bigip*\" OR TO_LOWER(COALESCE(TO_STRING(ci.class_name), \"\")) LIKE \"*f5*\" OR TO_LOWER(COALESCE(TO_STRING(ci.class_name), \"\")) LIKE \"*dns*\" OR TO_LOWER(COALESCE(TO_STRING(ci.class_name), \"\")) LIKE \"*communication*\", \"Network\", TO_LOWER(COALESCE(TO_STRING(ci.class_name), \"\")) LIKE \"*server*\" OR TO_LOWER(COALESCE(TO_STRING(ci.class_name), \"\")) LIKE \"*linux*\" OR TO_LOWER(COALESCE(TO_STRING(ci.class_name), \"\")) LIKE \"*windows*\" OR TO_LOWER(COALESCE(TO_STRING(ci.class_name), \"\")) LIKE \"*win_*\" OR TO_LOWER(COALESCE(TO_STRING(ci.class_name), \"\")) LIKE \"*aix*\" OR TO_LOWER(COALESCE(TO_STRING(ci.class_name), \"\")) LIKE \"*solaris*\" OR TO_LOWER(COALESCE(TO_STRING(ci.class_name), \"\")) LIKE \"*unix*\" OR TO_LOWER(COALESCE(TO_STRING(ci.class_name), \"\")) LIKE \"*computer*\" OR TO_LOWER(COALESCE(TO_STRING(ci.class_name), \"\")) LIKE \"*mainframe*\" OR TO_LOWER(COALESCE(TO_STRING(ci.class_name), \"\")) LIKE \"*lpar*\" OR TO_LOWER(COALESCE(TO_STRING(ci.class_name), \"\")) LIKE \"*storage*\" OR TO_LOWER(COALESCE(TO_STRING(ci.class_name), \"\")) LIKE \"*hardware*\", \"Server\", TO_LOWER(COALESCE(TO_STRING(ci.class_name), \"\")) LIKE \"*application*\" OR TO_LOWER(COALESCE(TO_STRING(ci.class_name), \"\")) LIKE \"*service*\" OR TO_LOWER(COALESCE(TO_STRING(ci.class_name), \"\")) LIKE \"*business*\" OR TO_LOWER(COALESCE(TO_STRING(ci.class_name), \"\")) LIKE \"*app*\" OR TO_LOWER(COALESCE(TO_STRING(ci.class_name), \"\")) LIKE \"*batch*\", \"Application\", \"Other\"), pri = TO_INTEGER(priority),\n       age_minutes = DATE_DIFF(\"minutes\", TO_DATETIME(opened_at), NOW())\n| WHERE domain IN (\"Server\", \"Database\", \"Middleware\", \"VMware\", \"Cloud\", \"Network\", \"Unknown\", \"Other\")\n| STATS p1 = COUNT_DISTINCT(CASE(pri == 1, number)), p2 = COUNT_DISTINCT(CASE(pri == 2, number)) BY domain"
   }
