  {
   "name": "al",
   "url": {
    "%type%": "esql",
    "query": "FROM .ds-bridge-alerts-netcool-default-*, .alerts-observability.* METADATA _index\n| EVAL nc = _index LIKE \"*netcool*\"\n| WHERE (nc AND @timestamp >= NOW() - 24 hours AND (TO_STRING(ci.environment) IS NULL OR TO_STRING(ci.environment) IN (\"\", \"null\") OR TO_LOWER(TO_STRING(ci.environment)) LIKE \"prod*\" OR TO_LOWER(TO_STRING(ci.environment)) LIKE \"prd*\"))\n     OR (NOT nc AND @timestamp >= NOW() - 7 days AND TO_STRING(kibana.alert.status) == \"active\"\n         AND TO_STRING(kibana.alert.rule.name) LIKE \"paladin*\")\n| EVAL rule = TO_LOWER(TO_STRING(kibana.alert.rule.name)),\n       ekey = CONCAT(COALESCE(TO_STRING(kibana.alert.rule.name), \"\"), \"|\", COALESCE(TO_STRING(kibana.alert.instance.id), \"\")),\n       akey = CASE(nc, CONCAT(\"n|\", COALESCE(TO_STRING(netcool.identifier), \"\")), CONCAT(\"e|\", ekey)),\n       eparts = SPLIT(REPLACE(TO_LOWER(TO_STRING(kibana.alert.instance.id)), \"#\", \",\"), \",\"),\n       ehead = MV_FIRST(SPLIT(REPLACE(TO_LOWER(TO_STRING(kibana.alert.instance.id)), \"#\", \",\"), \",\"))\n| EVAL ci_e = CASE(MV_COUNT(eparts) > 1 AND LENGTH(ehead) == 32, MV_FIRST(MV_SLICE(eparts, 1, 1)), ehead),\n       esev = TO_LOWER(TO_STRING(kibana.alert.severity)),\n       rec = CONCAT(TO_STRING(TO_LONG(@timestamp)), \"~\", COALESCE(TO_STRING(severity), \"9\"), \"~\",\n                    COALESCE(TO_STRING(netcool.type_name), \"problem\"), \"~\",\n                    COALESCE(TO_STRING(message), TO_STRING(kibana.alert.reason), TO_STRING(kibana.alert.rule.name), \"\"))\n| EVAL erank = CASE(nc, null, esev == \"critical\", 3, esev IN (\"low\", \"minor\", \"warning\", \"medium\"), 1, 2)\n| STATS latest = MAX(rec), nsev = MAX(CASE(nc AND severity > 0, severity)), erank = MAX(erank),\n        ci_n = VALUES(TO_STRING(ci.name)), node_n = VALUES(TO_STRING(node)), cls = VALUES(TO_STRING(ci.class_name)),\n        ci_es = VALUES(ci_e), rules = VALUES(rule), started = MIN(COALESCE(TO_DATETIME(first_occurrence), TO_DATETIME(kibana.alert.start), @timestamp))\n  BY akey, nc\n| DISSECT latest \"%{ts}~%{sev_now}~%{type_now}~%{summary}\"\n| WHERE NOT nc OR (sev_now != \"0\" AND type_now != \"resolution\")\n| EVAL rule1 = COALESCE(MV_FIRST(rules), \"\"), cls1 = MV_FIRST(cls),\n       severity_label = CASE(nc AND nsev == 5, \"Critical\", nc AND nsev == 4, \"Major\", nc, \"Minor\",\n                             erank == 3, \"Critical\", erank == 1, \"Minor\", \"Major\"),\n       domain = CASE(nc AND cls1 IS NULL, \"Network\",\n                     nc, CASE(TO_LOWER(COALESCE(cls1, \"\")) == \"\" OR TO_LOWER(COALESCE(cls1, \"\")) == \"null\", \"Unknown\", TO_LOWER(COALESCE(cls1, \"\")) LIKE \"*infrastructure service*\", \"Other\", TO_LOWER(COALESCE(cls1, \"\")) LIKE \"*esx*\" OR TO_LOWER(COALESCE(cls1, \"\")) LIKE \"*vmware*\" OR TO_LOWER(COALESCE(cls1, \"\")) LIKE \"*vcenter*\" OR TO_LOWER(COALESCE(cls1, \"\")) LIKE \"*vsphere*\" OR TO_LOWER(COALESCE(cls1, \"\")) LIKE \"*hyper_v*\" OR TO_LOWER(COALESCE(cls1, \"\")) LIKE \"*hyper-v*\", \"VMware\", TO_LOWER(COALESCE(cls1, \"\")) LIKE \"*sql*\" OR TO_LOWER(COALESCE(cls1, \"\")) LIKE \"*oracle*\" OR TO_LOWER(COALESCE(cls1, \"\")) LIKE \"*db2*\" OR TO_LOWER(COALESCE(cls1, \"\")) LIKE \"*database*\" OR TO_LOWER(COALESCE(cls1, \"\")) LIKE \"*postgres*\" OR TO_LOWER(COALESCE(cls1, \"\")) LIKE \"*mongo*\" OR TO_LOWER(COALESCE(cls1, \"\")) LIKE \"*sybase*\" OR TO_LOWER(COALESCE(cls1, \"\")) LIKE \"*_db*\" OR TO_LOWER(COALESCE(cls1, \"\")) LIKE \"*db_*\", \"Database\", TO_LOWER(COALESCE(cls1, \"\")) LIKE \"*mq*\" OR TO_LOWER(COALESCE(cls1, \"\")) LIKE \"*websphere*\" OR TO_LOWER(COALESCE(cls1, \"\")) LIKE \"*jboss*\" OR TO_LOWER(COALESCE(cls1, \"\")) LIKE \"*tomcat*\" OR TO_LOWER(COALESCE(cls1, \"\")) LIKE \"*weblogic*\" OR TO_LOWER(COALESCE(cls1, \"\")) LIKE \"*iis*\" OR TO_LOWER(COALESCE(cls1, \"\")) LIKE \"*app_server*\" OR TO_LOWER(COALESCE(cls1, \"\")) LIKE \"*application server*\" OR TO_LOWER(COALESCE(cls1, \"\")) LIKE \"*web server*\" OR TO_LOWER(COALESCE(cls1, \"\")) LIKE \"*web_server*\" OR TO_LOWER(COALESCE(cls1, \"\")) LIKE \"*middleware*\", \"Middleware\", TO_LOWER(COALESCE(cls1, \"\")) LIKE \"*kubernetes*\" OR TO_LOWER(COALESCE(cls1, \"\")) LIKE \"*gke*\" OR TO_LOWER(COALESCE(cls1, \"\")) LIKE \"*cloud*\" OR TO_LOWER(COALESCE(cls1, \"\")) LIKE \"*gcp*\" OR TO_LOWER(COALESCE(cls1, \"\")) LIKE \"*container*\", \"Cloud\", TO_LOWER(COALESCE(cls1, \"\")) LIKE \"*switch*\" OR TO_LOWER(COALESCE(cls1, \"\")) LIKE \"*router*\" OR TO_LOWER(COALESCE(cls1, \"\")) LIKE \"*ups*\" OR TO_LOWER(COALESCE(cls1, \"\")) LIKE \"*firewall*\" OR TO_LOWER(COALESCE(cls1, \"\")) LIKE \"*load bal*\" OR TO_LOWER(COALESCE(cls1, \"\")) LIKE \"*lb_*\" OR TO_LOWER(COALESCE(cls1, \"\")) LIKE \"*network*\" OR TO_LOWER(COALESCE(cls1, \"\")) LIKE \"*wireless*\" OR TO_LOWER(COALESCE(cls1, \"\")) LIKE \"*access point*\" OR TO_LOWER(COALESCE(cls1, \"\")) LIKE \"*ip_*\" OR TO_LOWER(COALESCE(cls1, \"\")) LIKE \"*ip *\" OR TO_LOWER(COALESCE(cls1, \"\")) LIKE \"*netgear*\" OR TO_LOWER(COALESCE(cls1, \"\")) LIKE \"*pdu*\" OR TO_LOWER(COALESCE(cls1, \"\")) LIKE \"*big-ip*\" OR TO_LOWER(COALESCE(cls1, \"\")) LIKE \"*bigip*\" OR TO_LOWER(COALESCE(cls1, \"\")) LIKE \"*f5*\" OR TO_LOWER(COALESCE(cls1, \"\")) LIKE \"*dns*\" OR TO_LOWER(COALESCE(cls1, \"\")) LIKE \"*communication*\", \"Network\", TO_LOWER(COALESCE(cls1, \"\")) LIKE \"*server*\" OR TO_LOWER(COALESCE(cls1, \"\")) LIKE \"*linux*\" OR TO_LOWER(COALESCE(cls1, \"\")) LIKE \"*windows*\" OR TO_LOWER(COALESCE(cls1, \"\")) LIKE \"*win_*\" OR TO_LOWER(COALESCE(cls1, \"\")) LIKE \"*aix*\" OR TO_LOWER(COALESCE(cls1, \"\")) LIKE \"*solaris*\" OR TO_LOWER(COALESCE(cls1, \"\")) LIKE \"*unix*\" OR TO_LOWER(COALESCE(cls1, \"\")) LIKE \"*computer*\" OR TO_LOWER(COALESCE(cls1, \"\")) LIKE \"*mainframe*\" OR TO_LOWER(COALESCE(cls1, \"\")) LIKE \"*lpar*\" OR TO_LOWER(COALESCE(cls1, \"\")) LIKE \"*storage*\" OR TO_LOWER(COALESCE(cls1, \"\")) LIKE \"*hardware*\", \"Server\", TO_LOWER(COALESCE(cls1, \"\")) LIKE \"*application*\" OR TO_LOWER(COALESCE(cls1, \"\")) LIKE \"*service*\" OR TO_LOWER(COALESCE(cls1, \"\")) LIKE \"*business*\" OR TO_LOWER(COALESCE(cls1, \"\")) LIKE \"*app*\" OR TO_LOWER(COALESCE(cls1, \"\")) LIKE \"*batch*\", \"Application\", \"Other\"),\n                     rule1 LIKE \"*mq*\" OR rule1 LIKE \"*websphere*\" OR rule1 LIKE \"*jboss*\" OR rule1 LIKE \"*tomcat*\" OR rule1 LIKE \"*iis*\", \"Middleware\",\n                     rule1 LIKE \"*sql*\" OR rule1 LIKE \"*oracle*\" OR rule1 LIKE \"*db2*\" OR rule1 LIKE \"*database*\", \"Database\",\n                     rule1 LIKE \"*gke*\" OR rule1 LIKE \"*kubernetes*\", \"Cloud\",\n                     \"Server\"),\n       source = CASE(nc, \"Netcool\", \"Elastic\"),\n       ci = COALESCE(MV_FIRST(ci_n), MV_FIRST(node_n), MV_FIRST(ci_es), \"—\"),\n       sev_rank = CASE(severity_label == \"Critical\", 3, severity_label == \"Major\", 2, 1)\n| WHERE domain IN (\"Server\", \"Database\", \"Middleware\", \"VMware\", \"Cloud\", \"Network\", \"Unknown\", \"Other\")\n| STATS critical = SUM(CASE(severity_label == \"Critical\", 1, 0)), major = SUM(CASE(severity_label == \"Major\", 1, 0)), alerts = COUNT(*) BY domain"
   }
