  {
   "name": "srv",
   "url": {
    "%type%": "esql",
    "query": "FROM .ds-metrics-system.cpu-default*, .ds-metrics-system.memory-default*, .ds-metrics-system.filesystem-default*\n| WHERE @timestamp >= NOW() - 24 hours AND (TO_STRING(ci.environment) IS NULL OR TO_STRING(ci.environment) IN (\"\", \"null\") OR TO_LOWER(TO_STRING(ci.environment)) LIKE \"prod*\" OR TO_LOWER(TO_STRING(ci.environment)) LIKE \"prd*\")\n| EVAL recent = @timestamp >= NOW() - 1 hour,\n       cpu = CASE(recent, TO_DOUBLE(system.cpu.total.norm.pct)), mem = CASE(recent, TO_DOUBLE(system.memory.actual.used.pct)),\n       disk = CASE(recent, TO_DOUBLE(system.filesystem.used.pct)),\n       server = TO_LOWER(COALESCE(TO_STRING(ci.name), TO_STRING(host.name)))\n| STATS cpu_p90 = PERCENTILE(cpu, 90), mem_max = MAX(mem), disk_max = MAX(disk), last_seen = MAX(@timestamp) BY server\n| WHERE server IS NOT NULL\n| EVAL silent = CASE(DATE_DIFF(\"minutes\", last_seen, NOW()) > 10, 1, 0),\n       hot_cpu = CASE(cpu_p90 >= 0.9, 1, 0), hot_mem = CASE(mem_max >= 0.9, 1, 0), hot_disk = CASE(disk_max >= 0.9, 1, 0)\n| EVAL pressure = CASE(silent == 0 AND (hot_cpu == 1 OR hot_mem == 1 OR hot_disk == 1), 1, 0)\n| STATS servers = COUNT(*), silent = SUM(silent), pressure = SUM(pressure), disk = SUM(CASE(silent == 0, hot_disk, 0)), cpu = SUM(CASE(silent == 0, hot_cpu, 0)), mem = SUM(CASE(silent == 0, hot_mem, 0))"
   }
  },
  {
   "name": "gke",
   "url": {
    "%type%": "esql",
    "query": "FROM metrics-gcp.gke-*, cmdb-ci-relations* METADATA _index\n| WHERE (NOT _index LIKE \"*cmdb-ci-relations*\" AND @timestamp >= NOW() - 1 hour\n         AND (gcp.gke.node.cpu.allocatable_utilization.pct IS NOT NULL OR gcp.gke.node.memory.allocatable_utilization.pct IS NOT NULL\n              OR gcp.gke.node.memory.used.bytes IS NOT NULL OR gcp.gke.container.restart.count IS NOT NULL))\n     OR (_index LIKE \"*cmdb-ci-relations*\" AND \"(no CI selected)\" != \"(no CI selected)\"\n         AND (parent.name IN (\"(no CI selected)\", TO_UPPER(\"(no CI selected)\"), TO_LOWER(\"(no CI selected)\")) OR child.name IN (\"(no CI selected)\", TO_UPPER(\"(no CI selected)\"), TO_LOWER(\"(no CI selected)\")))\n         AND (TO_STRING(parent.class) == \"cmdb_ci_kubernetes_cluster\" OR TO_STRING(child.class) == \"cmdb_ci_kubernetes_cluster\")\n         AND COALESCE(TO_LOWER(TO_STRING(is_marked_for_deletion)), \"false\") != \"true\")\n| EVAL is_rel = _index LIKE \"*cmdb-ci-relations*\", ci_l = TO_LOWER(\"(no CI selected)\"),\n       p_l = TO_LOWER(TO_STRING(parent.name)), c_l = TO_LOWER(TO_STRING(child.name)),\n       cpu = TO_DOUBLE(gcp.gke.node.cpu.allocatable_utilization.pct), mem = TO_DOUBLE(gcp.gke.node.memory.allocatable_utilization.pct),\n       mu = CASE(TO_STRING(gcp.labels.metrics.memory_type) == \"evictable\", null, TO_DOUBLE(gcp.gke.node.memory.used.bytes)),\n       ma = TO_DOUBLE(gcp.gke.node.memory.allocatable.bytes),\n       rc = TO_DOUBLE(gcp.gke.container.restart.count)\n| EVAL cluster = CASE(is_rel, CASE(TO_STRING(child.class) == \"cmdb_ci_kubernetes_cluster\" AND (c_l != ci_l OR TO_STRING(parent.class) != \"cmdb_ci_kubernetes_cluster\"), c_l, p_l),\n                      TO_LOWER(TO_STRING(gcp.labels.resource.cluster_name))),\n       ent = CASE(is_rel, \"\", rc IS NOT NULL, CONCAT(\"c:\", COALESCE(TO_STRING(gcp.labels_fingerprint), \"\")), COALESCE(TO_STRING(gcp.labels.resource.node_name), \"\")),\n       project = CASE(is_rel, \"\", COALESCE(TO_STRING(cloud.account.id), \"\"))\n| STATS rel = MAX(CASE(is_rel, 1, 0)), cpu_avg_e = AVG(cpu), cpu_p90_e = PERCENTILE(cpu, 90), mem_u = MAX(mem), mem_used = MAX(mu), mem_alloc = MAX(ma),\n        r_max = MAX(rc), r_min = MIN(rc), last_e = MAX(CASE(NOT is_rel, @timestamp))\n  BY cluster, ent, project\n| EVAL restarts_e = r_max - r_min, mem_e = COALESCE(mem_u, mem_used / mem_alloc), project = CASE(project == \"\", null, project)\n| STATS related = MAX(rel), nodes = COUNT(cpu_p90_e), cpu_a = AVG(cpu_avg_e), cpu_p = MAX(cpu_p90_e), mem_p = MAX(mem_e),\n        restarts = SUM(restarts_e), last_seen = MAX(last_e), projects = VALUES(project)\n  BY cluster\n| WHERE COALESCE(cluster, \"\") != \"\" AND (\"(no CI selected)\" == \"(no CI selected)\" OR related == 1 OR cluster == TO_LOWER(\"(no CI selected)\"))\n| EVAL scale = CASE(COALESCE(cpu_p, 0) <= 2 AND COALESCE(mem_p, 0) <= 2, 100.0, 1.0)\n| EVAL cpu_avg = ROUND(cpu_a * scale, 1), cpu_p90 = ROUND(cpu_p * scale, 1), mem_peak = ROUND(mem_p * scale, 1),\n       restarts = CASE(last_seen IS NULL, null, COALESCE(TO_LONG(restarts), TO_LONG(0))), silent_min = DATE_DIFF(\"minutes\", last_seen, NOW()),\n       project = COALESCE(MV_FIRST(projects), \"—\")\n| EVAL status = CASE(last_seen IS NULL, \"Not collected\", silent_min > 20, \"Silent\",\n                     cpu_p90 >= 90 OR mem_peak >= 90, \"Critical\",\n                     cpu_p90 >= 80 OR mem_peak >= 80 OR restarts >= 10, \"Warning\", \"Healthy\"),\n       rank = CASE(status == \"Critical\", 1, status == \"Silent\", 2, status == \"Warning\", 3, status == \"Not collected\", 4, 5)\n| SORT rank ASC, cluster ASC\n| LIMIT 100\n| STATS clusters = COUNT(*), gke_bad = SUM(CASE(status IN (\"Critical\", \"Silent\"), 1, 0)), gke_warn = SUM(CASE(status == \"Warning\", 1, 0)), restarts = SUM(restarts)"
   }
